"""Server-rendered shell for the dependency-free Evaluation Center UI."""

from __future__ import annotations


def render_evaluations_html() -> str:
    return """<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>AI Evaluation Center · Req2Test</title>
  <style>
    :root{--ink:#15231d;--muted:#66746d;--line:#d9e0dc;--paper:#f6f4ed;--card:#fff;--accent:#186a49;--soft:#e8f1ec;--warn:#9a5a16}
    *{box-sizing:border-box} body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}
    nav{height:58px;padding:0 4vw;display:flex;align-items:center;gap:24px;border-bottom:1px solid var(--line);background:#fbfaf6}
    nav strong{font-size:16px;margin-right:auto} nav a{color:var(--muted);text-decoration:none} nav a.active{color:var(--ink);font-weight:650}
    main{max-width:1320px;margin:0 auto;padding:34px 28px 64px}.hero{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:26px}
    h1{font:600 36px/1.1 Georgia,serif;margin:0 0 8px}h2{font:600 21px/1.2 Georgia,serif;margin:0}.sub{color:var(--muted);max-width:720px}
    .grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:0 3px 14px #1832250a}.span{grid-column:1/-1}
    .head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.pill{border-radius:99px;padding:3px 9px;background:var(--soft);color:var(--accent);font-size:12px}
    label{display:block;color:var(--muted);font-size:12px;margin-bottom:5px}input,select{width:100%;padding:9px 10px;border:1px solid var(--line);border-radius:7px;background:white;color:var(--ink)}
    .fields{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.actions{display:flex;gap:10px;margin-top:14px}button{border:0;border-radius:7px;padding:9px 14px;background:var(--accent);color:#fff;cursor:pointer}button.secondary{background:#e9ecea;color:var(--ink)}
    table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);padding:10px 8px;vertical-align:top}th{font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)}
    .score{font:600 24px Georgia,serif}.muted{color:var(--muted)}.error{color:#9d322d}.empty{padding:20px 0;color:var(--muted)}
    details{margin:5px 0}pre{white-space:pre-wrap;word-break:break-word;background:#f7f8f6;padding:10px;border-radius:7px;font-size:12px}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{padding:12px;border:1px solid var(--line);border-radius:8px}.metric b{display:block;font-size:18px}
    @media(max-width:850px){.grid,.fields,.metric-grid{grid-template-columns:1fr}.span{grid-column:auto}.hero{display:block}}
  </style>
</head>
<body>
<nav><strong>REQ2TEST</strong><a href="/workbench">Workbench</a><a href="/tasks">Tasks</a><a href="/knowledge">Knowledge</a><a class="active" href="/evaluations">Evaluation</a><a href="/system">System</a></nav>
<main>
  <section class="hero"><div><h1>AI Evaluation Center</h1><div class="sub">对固定 Golden Dataset 运行可追踪的离线回归或模型 / Prompt A-B 实验。Evaluation Center 与生成流程中的 Review Agent 相互独立。</div></div><span class="pill">deterministic-first</span></section>
  <div class="grid">
    <section class="card"><div class="head"><h2>Golden Datasets</h2><span id="datasetCount" class="pill">—</span></div><div id="datasets" class="empty">正在加载…</div></section>
    <section class="card"><div class="head"><h2>创建 Eval Run</h2></div><div class="fields"><div><label>Dataset</label><select id="runDataset"></select></div><div><label>模式</label><select id="runMode"><option value="demo">Demo（离线）</option><option value="openai_compatible">OpenAI-compatible / Ollama</option></select></div><div><label>模型</label><input id="runModel" value="gpt-4.1-mini"></div><div><label>Prompt</label><select id="runPrompt"><option>workflow-v1</option><option>workflow-grounded-v2</option></select></div><div><label>Temperature</label><input id="runTemp" type="number" min="0" max="1" step="0.1" value="0.1"></div><div><label>Seed（可选）</label><input id="runSeed" type="number"></div><div><label>Base URL（在线模式）</label><input id="runBaseUrl" value="https://api.openai.com/v1"></div><div><label>API Key（不持久化）</label><input id="runApiKey" type="password" autocomplete="off"></div></div><div class="actions"><button onclick="createRun()">开始评测</button></div><div id="runMessage" class="muted"></div></section>
    <section class="card span"><div class="head"><h2>Evaluation Runs</h2><button class="secondary" onclick="loadRuns()">刷新</button></div><div id="runs" class="empty">正在加载…</div></section>
    <section class="card span"><div class="head"><h2>Run 详情</h2><span id="detailStatus" class="pill">选择一条 Run</span></div><div id="runDetail" class="empty">点击上方 Run 查看六项指标、失败原因与 evidence。</div></section>
    <section class="card span"><div class="head"><h2>Model / Prompt A-B Comparison</h2></div><div class="fields"><div><label>名称</label><input id="abName" value="Demo Prompt Comparison"></div><div><label>Dataset</label><select id="abDataset"></select></div><div><label>A Model</label><input id="aModel" value="gpt-4.1-mini"></div><div><label>B Model</label><input id="bModel" value="gpt-4.1-mini"></div><div><label>A Prompt</label><select id="aPrompt"><option>workflow-v1</option><option>workflow-grounded-v2</option></select></div><div><label>B Prompt</label><select id="bPrompt"><option>workflow-grounded-v2</option><option>workflow-v1</option></select></div><div><label>A Temperature</label><input id="aTemp" type="number" value="0.1" step="0.1"></div><div><label>B Temperature</label><input id="bTemp" type="number" value="0.1" step="0.1"></div></div><div class="actions"><button onclick="createComparison()">运行 A/B</button><button class="secondary" onclick="loadComparisons()">刷新</button></div><div id="abMessage" class="muted"></div><div id="comparisons" class="empty">正在加载…</div></section>
  </div>
</main>
<script>
const api=async(url,options={})=>{const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});if(r.status===401){location.href='/login?next=/evaluations';throw Error('需要登录')}const body=r.status===204?{}:await r.json();if(!r.ok)throw Error(body.detail||'请求失败');return body};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=v=>`<span class="pill">${esc(v)}</span>`;
async function loadDatasets(){try{const data=await api('/api/v1/evaluations/datasets');datasetCount.textContent=`${data.total} datasets`;datasets.innerHTML=data.items.length?`<table><thead><tr><th>Name</th><th>Version</th><th>Cases</th><th>Digest</th></tr></thead><tbody>${data.items.map(x=>`<tr><td><b>${esc(x.name)}</b><br><span class="muted">${esc(x.tags.join(', '))}</span></td><td>${esc(x.dataset_version)}</td><td>${x.case_count}</td><td><code>${esc(x.digest.slice(0,12))}…</code></td></tr>`).join('')}</tbody></table>`:'<div class="empty">没有发现数据集</div>';const opts=data.items.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} · ${esc(x.dataset_version)}</option>`).join('');runDataset.innerHTML=opts;abDataset.innerHTML=opts}catch(e){datasets.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
async function loadRuns(){try{const data=await api('/api/v1/evaluations/runs');runs.innerHTML=data.items.length?`<table><thead><tr><th>Run</th><th>Config</th><th>Status</th><th>Score</th><th>Latency</th><th>Created</th></tr></thead><tbody>${data.items.map(x=>`<tr onclick="showRun('${x.id}')" style="cursor:pointer"><td><code>${x.id.slice(0,8)}</code><br>${esc(x.dataset_version)}</td><td>${esc(x.provider)} / ${esc(x.model)}<br><span class="muted">${esc(x.prompt_version)}</span></td><td>${status(x.status)}</td><td class="score">${x.overall_score??'—'}</td><td>${x.latency_ms==null?'—':x.latency_ms+' ms'}</td><td>${esc(x.created_at||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚无评测运行</div>'}catch(e){runs.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
async function showRun(id){try{const x=await api('/api/v1/evaluations/runs/'+id);detailStatus.textContent=x.status;const metrics=Object.entries(x.metric_scores||{}).map(([k,v])=>`<div class="metric"><span class="muted">${esc(k)}</span><b>${v}</b></div>`).join('');const cases=(x.cases||[]).map(c=>`<details><summary><b>${esc(c.dataset_case_id)}</b> · ${c.overall_score} · ${esc(c.failure_reason||'completed')}</summary>${Object.entries(c.metric_scores||{}).map(([n,m])=>`<p><b>${esc(n)} ${m.score}</b> — ${esc(m.reason)}</p><pre>${esc(JSON.stringify(m.evidence,null,2))}</pre>`).join('')}</details>`).join('');runDetail.innerHTML=`<div class="metric-grid">${metrics}</div><p>Overall <span class="score">${x.overall_score??'—'}</span> · revisions ${x.revision_iterations} · ${x.latency_ms??'—'} ms</p>${x.failure_reason?`<p class="error">${esc(x.failure_reason)}</p>`:''}${cases}`;if(['queued','running'].includes(x.status))setTimeout(()=>showRun(id),1800)}catch(e){runDetail.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
function config(prompt,temp,model=runModel.value){const mode=runMode.value;const seed=runSeed.value===''?null:Number(runSeed.value);return{llm_settings:{mode,model,temperature:Number(temp),seed,api_key:runApiKey.value,base_url:runBaseUrl.value,timeout_seconds:90},generation_config:{prompt_version:prompt,include_positive:true,include_negative:true,include_edge:false,max_cases:12,min_review_score:85,max_review_iterations:1}}}
async function createRun(){try{runMessage.textContent='正在创建…';const data=await api('/api/v1/evaluations/runs',{method:'POST',body:JSON.stringify({dataset_name:runDataset.value,configuration:config(runPrompt.value,runTemp.value)})});runApiKey.value='';runMessage.textContent='Run 已进入队列：'+data.run.id;await loadRuns();showRun(data.run.id)}catch(e){runMessage.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
async function createComparison(){try{abMessage.textContent='正在创建 A/B…';const data=await api('/api/v1/evaluations/comparisons',{method:'POST',body:JSON.stringify({name:abName.value,dataset_name:abDataset.value,configuration_a:config(aPrompt.value,aTemp.value,aModel.value),configuration_b:config(bPrompt.value,bTemp.value,bModel.value)})});runApiKey.value='';abMessage.textContent='Comparison 已进入队列：'+data.comparison.id;loadComparisons()}catch(e){abMessage.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
async function loadComparisons(){try{const data=await api('/api/v1/evaluations/comparisons');comparisons.innerHTML=data.items.length?`<table><thead><tr><th>Name</th><th>Status</th><th>Dataset</th><th>Result</th></tr></thead><tbody>${data.items.map(x=>`<tr onclick="showComparison('${x.id}')" style="cursor:pointer"><td>${esc(x.name)}</td><td>${status(x.status)}</td><td>${esc(x.dataset_version)}</td><td>${x.summary.overall?`A ${x.summary.overall.configuration_a} / B ${x.summary.overall.configuration_b} / Δ ${x.summary.overall.delta}`:'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚无 A/B 对比</div>'}catch(e){comparisons.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
async function showComparison(id){try{const x=await api('/api/v1/evaluations/comparisons/'+id);const summary=x.summary||{};const rows=Object.entries(summary.metrics||{}).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${v.configuration_a}</td><td>${v.configuration_b}</td><td>${v.delta}</td></tr>`).join('');const totals=[['overall',summary.overall],['latency_ms',summary.latency_ms],['revision_iterations',summary.revision_iterations]].filter(([,v])=>v).map(([n,v])=>`<tr><td><b>${esc(n)}</b></td><td>${v.configuration_a}</td><td>${v.configuration_b}</td><td>${v.delta}</td></tr>`).join('');comparisons.innerHTML=`<p><b>${esc(x.name)}</b> ${status(x.status)}</p><table><thead><tr><th>Metric</th><th>A</th><th>B</th><th>Delta (B-A)</th></tr></thead><tbody>${rows}${totals}</tbody></table>${x.failure_reason?`<p class="error">${esc(x.failure_reason)}</p>`:''}`;if(['queued','running'].includes(x.status))setTimeout(()=>showComparison(id),1800)}catch(e){comparisons.innerHTML=`<span class="error">${esc(e.message)}</span>`}}
loadDatasets();loadRuns();loadComparisons();setInterval(()=>{loadRuns();loadComparisons()},10000);
</script>
</body></html>"""
